// ai-agents/harness/src/checks/prove-regression.ts: sketch: the bug fixers' proof before "done" (runs inside the VM)
import { copyFile, mkdir } from "node:fs/promises";
import { dirname, join } from "node:path";

export interface RegressionProof {
  failsWithoutFix: boolean;
  passesWithFix: boolean;
  baseLog: string;
  headLog: string;
}

/** Run the new test twice: on the base commit with only the test files added, then on the fix. */
export async function proveRegressionTest(
  vm: Vm, baseSha: string, testFiles: string[], testCmd: string): Promise<RegressionProof> {
  await vm.exec("git", ["-C", "/work/fcp", "worktree", "add", "/work/base", baseSha]);
  for (const path of testFiles) {  // the test, not the fix
    await mkdir(dirname(join("/work/base", path)), { recursive: true });
    await copyFile(join("/work/fcp", path), join("/work/base", path));
  }

  const base = await vm.exec("bash", ["-c", testCmd], { cwd: "/work/base" });  // must fail
  const head = await vm.exec("bash", ["-c", testCmd], { cwd: "/work/fcp" });   // must pass
  await vm.exec("git", ["-C", "/work/fcp", "worktree", "remove", "--force", "/work/base"]);
  return {
    // An ImportError because the test imports something the fix added is a setup error, not a
    // reproduction: the fixer rewrites the test so it fails on behaviour.
    failsWithoutFix: base.code !== 0 && !base.isSetupError,
    passesWithFix: head.code === 0,
    baseLog: base.tail(80), headLog: head.tail(80),
  };
}

// Stop hook: a bug fixer is not "done" until both are true; the PR shows both logs side by side.

// frontend/e2e/pr/rh-xxxx-projects-search-reset.spec.ts: sketch of a regression spec the FE bug fixer writes (example bug)
import {expect, test} from "../fixtures"

test.use({video: "on"}) // the proof in the PR, recorded on fake seed data only

test.describe("RH-XXXX: clearing the projects search lists every project again", () => {
	test("shows a project that the search had hidden once the search is cleared", async ({auth, apiSetup, projectsPage}) => {
		let alpha: {projectUid: string; projectName: string}
		let beta: {projectUid: string; projectName: string}
		await test.step("Given two projects on seed data", async () => {
			await auth.loginWithApi()
			alpha = await apiSetup.createProject("Bug repro alpha")
			beta = await apiSetup.createProject("Bug repro beta")
			await projectsPage.gotoWithRetry("/projects", /\/projects/)
		})
		await test.step("When I search for one project and then clear the search", async () => {
			await projectsPage.searchProjects(alpha.projectName)
			await projectsPage.clearProjectsSearch()
		})
		await test.step("Then the other project is listed again", async () => {
			await expect(projectsPage.getProjectCardByUid(beta.projectUid)).toBeVisible() // fails on main, passes with the fix
		})
	})
})

// ai-agents/harness/src/checks/flaky.ts: sketch: the flaky-test fixer's reproduce step and its proof (runs inside the VM)
const UNIT = "./scripts/local_run_backend_unit_tests.sh";  // forwards extra args to manage.py test
function runOnce(vm: Vm, component: string, label: string, seed: number): Promise<ExecResult> {
  // --shuffle changes the test order; running the whole module shows shared-state flakes
  return vm.exec(UNIT, [component, label, "--shuffle", String(seed), "--keepdb"], { cwd: "/work/fcp" });
}
export async function reproduceFlake(vm: Vm, component: string, label: string, tries = 200): Promise<FlakeRepro | undefined> {
  for (let i = 0; i < tries; i++) {
    const r = await runOnce(vm, component, label, 1000 + i);
    if (r.code !== 0) {
      return { seed: 1000 + i, attempt: i + 1, log: r.tail(120) };  // the seed makes it repeatable
    }
  }
  return undefined;  // no failure in 200 runs: hand back with the seeds tried
}
export async function proveStable(vm: Vm, component: string, label: string, runs = 50): Promise<StableProof> {
  for (let i = 0; i < runs; i++) {
    const r = await runOnce(vm, component, label, 5000 + i);
    if (r.code !== 0) {
      return { ok: false, greenInARow: i, failingSeed: 5000 + i, log: r.tail(120) };
    }
  }
  return { ok: true, greenInARow: runs };  // the PR shows 50/50 and the seed that used to fail
}
